BASE_DIR = Path(__file__).resolve().parent
HTML_FILE = BASE_DIR / "flores_amarillas.html"
HOST = "127.0.0.1"
PORT = 8000

HTML_FILE.write_text(HTML, encoding="utf-8")


class Handler(SimpleHTTPRequestHandler):
    def __init__(self, *args, **kwargs):
        super().__init__(*args, directory=str(BASE_DIR), **kwargs)


def abrir_navegador():
    webbrowser.open(f"http://{HOST}:{PORT}/flores_amarillas.html")


if __name__ == "__main__":
    servidor = ThreadingHTTPServer((HOST, PORT), Handler)
    print(f"Página disponible en: http://{HOST}:{PORT}/flores_amarillas.html")
    print("Presiona Ctrl+C para detener el servidor.")

    threading.Timer(0.8, abrir_navegador).start()

    try:
        servidor.serve_forever()
    except KeyboardInterrupt:
        print("\nServidor detenido.")
    finally:
        servidor.server_close()
